Item {
    id: root

    property bool hasBar: true
    property var themeColors: null
    property var isVisible: false

    signal wallpaperSelected(string imagePath)
    signal colorsGenerated() 

    property string wallpaperDirectory: "file:///home/lugo/Pictures/Wallpapers/"

    // MATEMÁTICAS: Mantenemos tus dimensiones rectangulares 16:9
    property int itemHeight: 130 // Apa, vi que lo subiste a 130, lo mantengo así
    property int itemWidth: itemHeight * 16 / 9 
    property int selectedBorderSize: 3
    property color selectedColor: themeColors ? themeColors.c1 : "#2196F3" // Usamos tu c1 de Hellwal

    // Curvatura de las esquinas para las imágenes y el borde
    property int imageCornerRadius: 20 // Súbelo o bájalo según te guste más

    implicitHeight: isVisible ? 150 : 0
    anchors { 
        left: parent.left 
        right: parent.right 
        bottom: parent.bottom 
        leftMargin: hasBar ? 80 : 30   
        rightMargin: 30  
    }

    Behavior on implicitHeight {
        NumberAnimation {
            duration: 800 
            easing.type: Easing.OutExpo
        }
    }

    onIsVisibleChanged: {
        if (isVisible) {
            wallpaperList.forceActiveFocus()
            if (wallpaperList.currentIndex === -1) {
                wallpaperList.currentIndex = 0;
            }
        }
    }

    Process {
        id: applyWallpaperScript
        onExited: (exitCode, exitStatus) => {
            if (exitCode === 0) {
                root.colorsGenerated()
            }
        }
    }

    function selectWallpaper(qmlUrl, bashPath) {
        applyWallpaperScript.command = ["bash", "/home/lugo/Projects/ZShell/scripts/changeWallpaper.sh", bashPath]
        applyWallpaperScript.running = true
        root.wallpaperSelected(qmlUrl)
    }

    Rectangle {
        anchors.fill: parent
        color: "transparent" 

        FolderListModel {
            id: wallpaperModel
            folder: root.wallpaperDirectory
            nameFilters: ["*.jpg", "*.jpeg", "*.png", "*.webp", "*.JPG", "*.JPEG", "*.PNG", "*.WEBP"]
            showDirs: false
        }

        ListView {
            id: wallpaperList
            anchors.left: parent.left
            anchors.right: parent.right
            anchors.margins: 0 
            // Mantenemos tu centrado vertical dinámico
            height: isVisible ? root.itemHeight : 0
            anchors.verticalCenter: parent.verticalCenter 

            orientation: ListView.Horizontal
            model: wallpaperModel
            spacing: 20
            clip: true

            focus: true 
            keyNavigationWraps: true 

            preferredHighlightBegin: (width / 2) - (root.itemWidth / 2)
            preferredHighlightEnd: (width / 2) + (root.itemWidth / 2)
            highlightRangeMode: ListView.StrictlyEnforceRange

            Keys.onLeftPressed: decrementCurrentIndex()
            Keys.onRightPressed: incrementCurrentIndex()

            Keys.onReturnPressed: {
                if (currentItem) {
                    root.selectWallpaper(currentItem.qmlUrl, currentItem.bashPath)
                }
            }

            delegate: Item {
                id: delegateItem
                width: root.itemWidth
                height: root.itemHeight

                property string qmlUrl: fileUrl 
                property string bashPath: filePath

                // --- NUEVO CONTENEDOR VISUAL CON ESQUINAS REDONDEADAS ---
                // Rectangle transparente para manejar el scale: 1.2 sin romper los bordes
                Rectangle {
                    anchors.fill: parent
                    color: "transparent"

                    // 1. EL CONTENEDOR CLIPPING (RECORTADOR) DE LA IMAGEN
                    Rectangle {
                        anchors.fill: parent
                        color: "#222" // Color de fondo si la imagen tarda en cargar
                        radius: root.imageCornerRadius // Redondeamos el contenedor
                        clip: true // ¡ESTO ES LO IMPORTANTE! Recorta la imagen a la curva
                        smooth: true

                        Image {
                            anchors.fill: parent
                            // Quitamos márgenes para que la imagen llene la curva
                            source: fileUrl 
                            fillMode: Image.PreserveAspectCrop 
                            smooth: true
                        }
                    }

                    // 2. EL BORDE DE SELECCIÓN REDONDEADO
                    Rectangle {
                        id: borderRectangle
                        anchors.fill: parent
                        radius: root.imageCornerRadius // Mismo radio que el clip
                        border.width: root.selectedBorderSize
                        border.color: "transparent" // Controlado por estados
                        color: "transparent" // Fondo transparente para no tapar la imagen
                        visible: false // Controlado por estados
                    }
                }

                MouseArea {
                    anchors.fill: parent
                    onClicked: {
                        wallpaperList.currentIndex = index
                        root.selectWallpaper(fileUrl, filePath)
                    }
                }

                states: [
                    State {
                        name: "selected"
                        when: index === wallpaperList.currentIndex
                        // Re-activamos la lógica visual de selección
                        PropertyChanges { target: borderRectangle; border.color: root.selectedColor; visible: true }
                        PropertyChanges { target: delegateItem; scale: 1.2 } 
                    }
                ]

                transitions: Transition {
                    from: ""; to: "selected"
                    reversible: true
                    ParallelAnimation {
                        ColorAnimation { target: borderRectangle; property: "border.color"; duration: 150 }
                        NumberAnimation { target: delegateItem; property: "scale"; duration: 150; easing.type: Easing.OutQuad }
                    }
                }
            }
        }
    }
}

