                    ParallelAnimation {
                        ColorAnimation { target: borderRectangle; property: "border.color"; duration: 150 }
                        NumberAnimation { target: delegateItem; property: "scale"; duration: 150; easing.type: Easing.OutQuad }
                    }
                }
            }
