import QtQuick
import Quickshell
import Quickshell.Io
import Quickshell.Services.Mpris

Item {
    id: root
    implicitHeight: 40
    anchors { 
        left: parent.left 
        right: parent.right 
        bottom: parent.bottom 
        leftMargin: hasBar ? 50 : 5   
        rightMargin: 5  
    }


    property var hasBar: null
    property int widthBarra: 8
    property int barSpace: 4
    property real sensitivity: 3
    property var themeColors: null
    property var isVisible: false


    property int barrasDinamicas: Math.max(10, Math.floor((root.width * 2) / (widthBarra + barSpace)))


    visible: isVisible


    property var cavaValues: []

    Process {
        id: cavaProcess
        command: [
            "bash", 
            "-c", 
            "echo -e '[general]\nbars=" + root.barrasDinamicas + "\nframerate=60\n[output]\nmethod=raw\nraw_target=/dev/stdout\ndata_format=ascii\nascii_max_range=100' > /tmp/quickshell_cava && cava -p /tmp/quickshell_cava"
        ]

        running: isVisible 

        stdout: SplitParser {
            onRead: data => {
                let text = data.toString().trim();
                if (text.length > 0) {
                    let values = text.split(';');
                    if (values[values.length - 1] === "") {
                        values.pop();
                    }

                    let newValues = [];
                    for (let i = 0; i < values.length; i++) {
                        newValues.push(parseInt(values[i]) || 0);
                    }
                    root.cavaValues = newValues;
                }
            }
        }
    }

    Row {

        anchors.horizontalCenter: parent.horizontalCenter
        height: parent.height 
        spacing: root.barSpace 

        anchors {
            right: parent.right
            left: parent.right 
            bottom: parent.bottom
            leftMargin: parent.leftMargin
            rightMargin: parent.rightMargin
        }

        Repeater {
            model: root.cavaValues.length

            Rectangle {
                width: root.widthBarra

                property real alturaCalculada: (root.cavaValues[index] / 100) * root.height * root.sensitivity
                height: Math.max(2, Math.min(root.height, alturaCalculada))

                color: themeColors.c1 
                radius: 4
                anchors.bottom: parent.bottom

                Behavior on height {
                    NumberAnimation { duration: 60; easing.type: Easing.OutQuad }
                }
            }
        }
    }
}

// 4. SHAPE INFERIOR (El rojo de abajo)
    Shape {
        anchors.right: mainRect.left
        anchors.bottom: mainRect.bottom 
        width: curveRadius
        height: curveRadius
        // opacity: isOpen ? 1 : 0

        ShapePath {
            fillColor: mainRect.color
            strokeColor: "transparent"
            PathSvg { 
                // Empieza Abajo-Izq -> Línea a Abajo-Der -> Línea a Arriba-Der -> Curva hueca hacia Abajo-Izq
                path: `M 0 ${curveRadius} L ${curveRadius} ${curveRadius} L ${curveRadius} 0 C ${curveRadius} ${curveRadius*0.45}, ${curveRadius*0.55} ${curveRadius}, 0 ${curveRadius} Z` 
            }
        }
    }

