import Quickshell
import Quickshell.Io
import QtQuick.Shapes

PanelWindow {
    id: root
    property int gapRight: 0
    property int curveRadius: 30

    // 1. El ancho de la ventana debe incluir el panel + el espacio para la curva
    property int baseWidth: rightPanelArea.containsMouse ? 500 : gapRight 
    implicitWidth: baseWidth > 0 ? (baseWidth + curveRadius) : 0

    exclusionMode: ExclusionMode.Ignore

    // IMPORTANTE: Fondo transparente para que la curva invertida deje ver el wallpaper
    color: "transparent" 

    anchors {
        right: true
        top: true
        bottom: true
    }

    // 2. Este es tu panel principal. Se ancla a la derecha de la ventana.
    Rectangle {
        id: mainRect
        width: root.baseWidth
        color: rightPanelArea.containsMouse ? "green" : "red"

        anchors {
            right: parent.right
            top: parent.top
            bottom: parent.bottom
        }

        MouseArea {
            id: rightPanelArea
            anchors.fill: parent
            hoverEnabled: true
        }
    }

    // 3. SHAPE SUPERIOR (El rojo de arriba en tu dibujo)
    Shape {
        // Se ancla a la izquierda de tu panel verde, y en la parte superior
        anchors.right: mainRect.left
        anchors.top: mainRect.top
        width: curveRadius
        height: curveRadius
        // opacity: isOpen ? 1 : 0

        ShapePath {
            // Vinculamos el color para que cambie junto con el rectángulo
            fillColor: mainRect.color 
            strokeColor: "transparent"
            PathSvg { 
                // Línea arriba -> Línea derecha -> Curva hacia el origen
                path: `M 0 0 L ${curveRadius} 0 L ${curveRadius} ${curveRadius} C ${curveRadius} ${curveRadius*0.45}, ${curveRadius*0.55} 0, 0 0 Z` 
            }
        }
    }

    // 4. SHAPE INFERIOR (El rojo de abajo en tu dibujo)
    Shape {
        // Se ancla a la izquierda de tu panel verde, y en la parte INFERIOR
        anchors.right: mainRect.left
        anchors.bottom: mainRect.bottom 
        width: curveRadius
        height: curveRadius
        // opacity: isOpen ? 1 : 0

        ShapePath {
            fillColor: mainRect.color
            strokeColor: "transparent"
            PathSvg { 
                // Empieza arriba-derecha -> Línea abajo -> Línea izquierda -> Curva hacia arriba-derecha
                path: `M ${curveRadius} 0 L ${curveRadius} ${curveRadius} L 0 ${curveRadius} C 0 ${curveRadius*0.45}, ${curveRadius*0.45} 0, ${curveRadius} 0 Z` 
            }
        }
    }
}

