import Quickshell
import Quickshell.Wayland
import Quickshell.Widgets
import Quickshell.Io    
import Quickshell.Hyprland
import Quickshell.Services.Mpris
import QtQuick
import QtCore
import "components/bar"
import "components"


ShellRoot {
    id: root
    property var spotifyPlayer: {
        let reproductores = Mpris.players.values;
        for (let i = 0; i < reproductores.length; i++) {
            if (reproductores[i].identity === "Spotify") {
                return reproductores[i];
            }
        }
        return null;
    }
    property bool hasMusic: spotifyPlayer ? (spotifyPlayer.playbackState === MprisPlaybackState.Playing) : false
    property int gapEdges: 4
    property int gapLeft: toggleBar ? gapEdges : 50
    property int gapBottom: hasMusic ? 40 : gapEdges
    property int gapRight: 40
    property int cornerRadius: 30
    property bool delayedHasMusic: false

    Timer {
        id: delayTimer
        interval: 500 
        repeat: false
        onTriggered: {
            delayedHasMusic = true
        }
    }

    onHasMusicChanged: {
        if (hasMusic) {
            delayTimer.restart()
        } else {
            delayTimer.stop()
            delayedHasMusic = false
        }
    }


    Settings {
        id: appSettings
        location: "file:///home/lugo/.cache/zshell_settings.conf" 
        property string savedWallpaper: ""
    }

    Loader {
        id: colorLoader
        source: "file:///home/lugo/.cache/hellwal/Colors.qml?t=" + new Date().getTime()
    }

    property color frameColor: colorLoader.item ? colorLoader.item.bg : "#050505"
    property bool toggleBar: false
    property string wallpaperSource: appSettings.savedWallpaper
    property bool toggleLauncher: false

    GlobalShortcut {
        appid: "zshell"
        name: "wallpaper" 
        onPressed: {
            wallpaperPicker.running = true;
        }
    }

    GlobalShortcut {
        appid: "zshell"
        name: "toggleBar" 
        onPressed: {
            toggleBar = !toggleBar
        }
    }



    Process {
        id: wallpaperPicker
        command: ["bash", "/home/lugo/Projects/ZShell/scripts/selector.sh"]

        // Solo guardamos la ruta aquí
        stdout: SplitParser {
            onRead: data => {
                let path = data.trim();
                if (path.length > 0) {
                    appSettings.savedWallpaper = "file://" + path;
                }
            }
        }

        // Recargamos los colores SOLO cuando el script terminó de ejecutarse
        onExited: (exitCode, exitStatus) => {
            if (exitCode === 0) {
                colorLoader.active = false; // Forzamos la descarga
                colorLoader.source = "file:///home/lugo/.cache/hellwal/Colors.qml?t=" + new Date().getTime();
                colorLoader.active = true;
            }
        }
    }

    PanelWindow {
        anchors { top: true; bottom: true; left: true; right: true }
        WlrLayershell.layer: WlrLayer.Background
        WlrLayershell.exclusionMode: ExclusionMode.Ignore 
        color: root.frameColor

        ClippingRectangle {
            anchors {
                fill: parent
                topMargin: root.gapEdges
                bottomMargin: root.gapBottom
                rightMargin: root.gapRight
                leftMargin: root.gapLeft
            }

            Behavior on anchors.leftMargin {
                NumberAnimation {
                    duration: 300 
                    easing.type: Easing.OutExpo
                }
            }

            Behavior on anchors.bottomMargin {
                NumberAnimation {
                    duration: 1000 
                    easing.type: Easing.OutExpo
                }
            }
            radius: root.cornerRadius 
            color: "black"

            Image {
                id: wallImage
                anchors.fill: parent
                source: root.wallpaperSource
                fillMode: Image.PreserveAspectCrop 
                smooth: true

                Behavior on source {
                    SequentialAnimation {
                        NumberAnimation { target: wallImage; property: "opacity"; to: 0; duration: 300 }
                        PropertyAction { target: wallImage; property: "source" }
                        NumberAnimation { target: wallImage; property: "opacity"; to: 1; duration: 300 }
                    }
                }
            }

        }


        Bar{visible: !root.toggleBar}
        Cava {themeColors: colorLoader.item; isVisible: delayedHasMusic; hasBar: !toggleBar}
        Launcher {themeColors: colorLoader.item; isOpen: toggleLauncher;}
        RightPanel{}

    }



    // --- Ventanas de exclusión ---
    PanelWindow {
        anchors { left: true; top: true; bottom: true }
        implicitWidth: 1
        WlrLayershell.exclusionMode: WlrLayershell.Fixed
        exclusiveZone: root.gapLeft
        color: "transparent"
    }

    PanelWindow {
        anchors { top: true; left: true; right: true }
        implicitHeight: 1
        WlrLayershell.exclusionMode: WlrLayershell.Fixed
        exclusiveZone: root.gapEdges
        color: "transparent"
    }

    PanelWindow {
        anchors { right: true; top: true; bottom: true }
        implicitWidth: 1
        WlrLayershell.exclusionMode: WlrLayershell.Fixed
        exclusiveZone: root.gapRight
        color: "transparent"
    }

    PanelWindow {
        anchors { bottom: true; left: true; right: true }
        implicitHeight: 1
        WlrLayershell.exclusionMode: WlrLayershell.Fixed
        exclusiveZone: root.gapBottom
        color: "transparent"
    }
}

